# Expected slice values from CPython 3.15, covering ASCII, Unicode and wide bounds.
cases = [
    ('', None, None, 1, ''),
    ('', None, None, -1, ''),
    ('', 1, 3, 1, ''),
    ('', 3, 1, -1, ''),
    ('', 100, -100, -2, ''),
    ('', -100, 100, 3, ''),
    ('', None, None, 2, ''),
    ('', 4, 1, 2, ''),
    ('', 0, 0, -1, ''),
    ('', None, None, 1267650600228229401496703205376, ''),
    ('', None, None, -1267650600228229401496703205376, ''),
    ('', -3, -1, 1, ''),
    ('abcdef', None, None, 1, 'abcdef'),
    ('abcdef', None, None, -1, 'fedcba'),
    ('abcdef', 1, 3, 1, 'bc'),
    ('abcdef', 3, 1, -1, 'dc'),
    ('abcdef', 100, -100, -2, 'fdb'),
    ('abcdef', -100, 100, 3, 'ad'),
    ('abcdef', None, None, 2, 'ace'),
    ('abcdef', 4, 1, 2, ''),
    ('abcdef', 0, 0, -1, ''),
    ('abcdef', None, None, 1267650600228229401496703205376, 'a'),
    ('abcdef', None, None, -1267650600228229401496703205376, 'f'),
    ('abcdef', -3, -1, 1, 'de'),
    ('abcdefghijklmno', None, None, 1, 'abcdefghijklmno'),
    ('abcdefghijklmno', None, None, -1, 'onmlkjihgfedcba'),
    ('abcdefghijklmno', 1, 3, 1, 'bc'),
    ('abcdefghijklmno', 3, 1, -1, 'dc'),
    ('abcdefghijklmno', 100, -100, -2, 'omkigeca'),
    ('abcdefghijklmno', -100, 100, 3, 'adgjm'),
    ('abcdefghijklmno', None, None, 2, 'acegikmo'),
    ('abcdefghijklmno', 4, 1, 2, ''),
    ('abcdefghijklmno', 0, 0, -1, ''),
    ('abcdefghijklmno', None, None, 1267650600228229401496703205376, 'a'),
    ('abcdefghijklmno', None, None, -1267650600228229401496703205376, 'o'),
    ('abcdefghijklmno', -3, -1, 1, 'mn'),
    ('aé😀z', None, None, 1, 'aé😀z'),
    ('aé😀z', None, None, -1, 'z😀éa'),
    ('aé😀z', 1, 3, 1, 'é😀'),
    ('aé😀z', 3, 1, -1, 'z😀'),
    ('aé😀z', 100, -100, -2, 'zé'),
    ('aé😀z', -100, 100, 3, 'az'),
    ('aé😀z', None, None, 2, 'a😀'),
    ('aé😀z', 4, 1, 2, ''),
    ('aé😀z', 0, 0, -1, ''),
    ('aé😀z', None, None, 1267650600228229401496703205376, 'a'),
    ('aé😀z', None, None, -1267650600228229401496703205376, 'z'),
    ('aé😀z', -3, -1, 1, 'é😀'),
    ('é😀abcdefé', None, None, 1, 'é😀abcdefé'),
    ('é😀abcdefé', None, None, -1, 'éfedcba😀é'),
    ('é😀abcdefé', 1, 3, 1, '😀a'),
    ('é😀abcdefé', 3, 1, -1, 'ba'),
    ('é😀abcdefé', 100, -100, -2, 'éecaé'),
    ('é😀abcdefé', -100, 100, 3, 'ébe'),
    ('é😀abcdefé', None, None, 2, 'éaceé'),
    ('é😀abcdefé', 4, 1, 2, ''),
    ('é😀abcdefé', 0, 0, -1, ''),
    ('é😀abcdefé', None, None, 1267650600228229401496703205376, 'é'),
    ('é😀abcdefé', None, None, -1267650600228229401496703205376, 'é'),
    ('é😀abcdefé', -3, -1, 1, 'ef'),
    ('é😀abé😀abcdefé😀', None, None, 1, 'é😀abé😀abcdefé😀'),
    ('é😀abé😀abcdefé😀', None, None, -1, '😀éfedcba😀éba😀é'),
    ('é😀abé😀abcdefé😀', 1, 3, 1, '😀a'),
    ('é😀abé😀abcdefé😀', 3, 1, -1, 'ba'),
    ('é😀abé😀abcdefé😀', 100, -100, -2, '😀fdb😀b😀'),
    ('é😀abé😀abcdefé😀', -100, 100, 3, 'ébadé'),
    ('é😀abé😀abcdefé😀', None, None, 2, 'éaéaceé'),
    ('é😀abé😀abcdefé😀', 4, 1, 2, ''),
    ('é😀abé😀abcdefé😀', 0, 0, -1, ''),
    ('é😀abé😀abcdefé😀', None, None, 1267650600228229401496703205376, 'é'),
    ('é😀abé😀abcdefé😀', None, None, -1267650600228229401496703205376, '😀'),
    ('é😀abé😀abcdefé😀', -3, -1, 1, 'fé'),
]
for text, start, stop, step, expected in cases:
    assert text[start:stop:step] == expected
assert ('ACGT' * 25000)[12345:12363] == 'CGTACGTACGTACGTACG'
print('string slices ok')
